function renderReads(tab) {
  const grid = document.getElementById('readsGrid');
  const articles = readsData[tab] || readsData['top-reads'];
  grid.innerHTML = articles.map(a => `
    <div class="read-card">
      <div class="read-card-img" style="background: ${a.bg};">
        <svg width="32" height="32" fill="none" viewBox="0 0 24 24" stroke="rgba(2,131,141,0.15)" stroke-width="1"><path stroke-linecap="round" stroke-linejoin="round" d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h10a2 2 0 012 2v1m2 13a2 2 0 01-2-2V7m2 13a2 2 0 002-2V9a2 2 0 00-2-2h-2m-4-3H9M7 16h6M7 8h6v4H7V8z"/></svg>
      </div>
      <div class="read-card-body">
        <span class="cat-tag">${a.cat}</span>
        <h3>${a.title}</h3>
        <span class="meta">${a.time}</span>
      </div>
    </div>
  `).join('');
}

document.getElementById('readsTabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('tab')) {
    this.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    renderReads(e.target.dataset.tab);
